with lines as (select id, effective_from, currency, tier_value from price_tiers lateral view explode(tier_prices) e as tier_value) select date_trunc('week', effective_from) as week_start, currency, sort_array(collect_set(currency)) as currency_list, min(tier_value) as min_tier_value, count(*) as event_count, count(case when currency = 'USD' then 1 end) as usd_count, rank() over (partition by date_trunc('week', effective_from) order by min(tier_value) desc) as min_tier_value_rank from lines group by 1, 2;
